<h1>Segurança</h1><p>O acesso ao painel exige uma conta de administrador. Após 5 falhas por e-mail ou 20 por IP em 15 minutos, novas tentativas são temporariamente bloqueadas.</p>
<nav class="filter-tabs" aria-label="Registros"><a class="btn <?= $kind === 'acoes' ? '' : 'btn-outline' ?>" href="<?= e(url('/admin/seguranca')) ?>">Ações do painel</a><a class="btn <?= $kind === 'login' ? '' : 'btn-outline' ?>" href="<?= e(url('/admin/seguranca', ['tipo' => 'login'])) ?>">Tentativas de login</a></nav>
<form method="get" class="search-form"><input type="hidden" name="tipo" value="<?= e($kind) ?>"><label for="q"><?= $kind === 'login' ? 'Buscar por e-mail' : 'Buscar por responsável ou área' ?></label><div class="search-row"><input id="q" type="search" name="q" value="<?= e($q) ?>"><button class="btn">Buscar</button></div></form>
<?php if (!$rows): ?><p>Nenhum registro encontrado.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>Responsável</th><th>Registro</th><th>IP</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td data-label="Data"><?= e(format_date($row['created_at'])) ?></td><td data-label="Responsável"><?= e($kind === 'login' ? $row['email'] : ($row['actor'] ?? 'Sistema')) ?></td><td data-label="Registro"><?php if ($kind === 'login'): ?><?= (int) $row['success'] ? 'Login realizado' : 'Tentativa recusada' ?><?php else: ?><?= e($row['action']) ?> · <?= e($row['entity']) ?> <?= $row['entity_id'] ? 'nº ' . (int) $row['entity_id'] : '' ?><?php if ($row['details']): ?><details><summary>Detalhes</summary><pre class="audit-detail"><?= e($row['details']) ?></pre></details><?php endif; ?><?php endif; ?></td><td data-label="IP"><?= e($row['ip']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?= render_template('admin/_pagination', compact('page','pages','total') + ['path' => '/admin/seguranca','filters' => ['q' => $q,'tipo' => $kind]]) ?>
